109	    /** Move a claim to a new status; a change its current status does not allow is refused, and so
110	     *  is settling a claim by the user who opened it, and any change to a claim dated inside a closed
111	     *  period, and any change the permission matrix does not allow the user's role. A clerk settling a claim whose due is above the sheet's clerk limit leaves it pending
112	     *  a steward's approval instead; but settling a claim that needs a proof and has none is refused
113	     *  before the clerk limit is considered. */
114	    @Transactional
115	    public Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus to) {
116	        Claim claim = lock(sheetId, claimId);
117	        refuseClosed(sheetId, claim.getDate());
118	        if (!claim.getStatus().canBecome(to) || to == ClaimStatus.PENDING) {
119	            throw new ResponseStatusException(HttpStatus.CONFLICT,
120	                    "A " + claim.getStatus() + " claim cannot become " + to);
121	        }
122	        String action = switch (to) {
123	            case OPEN -> "open";
124	            case SETTLED -> "settle";
125	            default -> "void";
126	        };
127	        if (!roles.may(sheetId, user, action)) {
128	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not " + action + " a claim");
129	        }
130	        if (to == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
131	            throw new ResponseStatusException(HttpStatus.CONFLICT,
132	                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be settled before then");
133	        }
134	        if (to == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
135	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
136	                    "The user who opened a claim cannot settle it");
137	        }
138	        if (to == ClaimStatus.SETTLED) {
139	            refuseUnproved(sheetId, claim);
140	        }
141	        ClaimStatus becomes = to == ClaimStatus.SETTLED && overClerkLimit(sheetId, user, claim)
142	                ? ClaimStatus.PENDING : to;
143	        return rollup.tracking(sheetId, user, () -> {
144	            Person person = person(sheetId, claim.getPersonId());
145	            if (becomes == ClaimStatus.SETTLED) {
146	                // Settling fixes the due at what it is now, while the claim is still open (the figure a
147	                // statement bound it to, if any, and its late charge); later changes to rates, the
148	                // late percent and the sheet's today do not alter it.
149	                claim.setSettledDue(dues.figure(sheetId, person, claim));
150	            }
151	            // A void claim keeps the number it had (never reused).
152	            claim.setStatus(becomes);
153	            if (becomes == ClaimStatus.OPEN) {
154	                claim.setNumber(nextNumber(sheetId, claim.getDate()));
155	                claim.setOpenedBy(user);
156	            }
157	            logStatus(sheetId, user, person, claim);
158	            Claim saved = claims.saveAndFlush(claim);
159	            String event = switch (becomes) {
160	                case OPEN -> "CLAIM_OPENED";
161	                case PENDING -> "CLAIM_PENDING";
162	                case SETTLED -> "CLAIM_SETTLED";
163	                case VOID -> "CLAIM_VOIDED";
164	                case DRAFT -> throw new IllegalStateException("a claim never returns to DRAFT");
165	            };
166	            String line = record(event, sheetId, user, person, saved);
167	            if (becomes == ClaimStatus.SETTLED) {
168	                line += " due=" + dueText(saved.getSettledDue());
169	            }
170	            audit.recordOnCommit(line);
171	            return saved;
172	        });
173	    }
