359	     *  (a negative amount), the one of the number given, which must be a settled claim of the person,
360	     *  or else it is refused. */
361	    private Claim corrected(String sheetId, long personId, BigDecimal amount, String corrects) {
362	        if (amount.signum() >= 0) {
363	            return null;
364	        }
365	        return (corrects == null ? Optional.<Claim>empty()
366	                : claims.findBySheetIdAndPersonIdAndNumberAndStatus(sheetId, personId, corrects, ClaimStatus.SETTLED))
367	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.BAD_REQUEST,
368	                        "A negative amount must correct a settled claim of the same person"));
369	    }
370	
371	    /** Refuse a change to a claim dated on the day when the day falls inside a closed period. */
372	    private void refuseClosed(String sheetId, LocalDate day) {
373	        if (periods.closedOn(sheetId, day)) {
374	            throw new ResponseStatusException(HttpStatus.LOCKED, "That claim's period is closed");
375	        }
376	    }
377	
378	    /** Whether a clerk is settling a claim whose due is above the sheet's clerk limit in force on its today; a claim with
379	     *  no due (n/a) is within any limit, and a steward settles anything. */
380	    private boolean overClerkLimit(String sheetId, String user, Claim claim) {
381	        BigDecimal limit = sheets.clerkLimit(sheetId);
382	        if (limit == null || SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
383	            return false;
384	        }
385	        BigDecimal due = dues.figure(sheetId, person(sheetId, claim.getPersonId()), claim);
386	        return due != null && due.compareTo(limit) > 0;
387	    }
388	
389	    /** Refuse settling or approving a claim with no proofs whose due is above the sheet's proof
390	     *  threshold in force on the claim's date; a claim with no due (n/a) and a sheet with no threshold
391	     *  need none. */
392	    private void refuseUnproved(String sheetId, Claim claim) {
393	        BigDecimal threshold = sheets.proofThreshold(sheetId, claim.getDate());
394	        if (threshold == null || claim.getProofs() > 0) {
395	            return;
396	        }
397	        BigDecimal due = dues.figure(sheetId, person(sheetId, claim.getPersonId()), claim);
398	        if (due != null && due.compareTo(threshold) > 0) {
399	            throw new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED,
400	                    "A claim whose due is above the proof threshold needs a proof first");
401	        }
402	    }
403	
404	    /** Refuse a claim of the person dated after the day they are retired from. */
405	    private static void refuseRetired(Person person, LocalDate day) {
406	        if (person.getRetiredFrom() != null && day.isAfter(person.getRetiredFrom())) {
407	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
408	                    "A claim cannot be dated after the person's retirement");
409	        }
410	    }
411	
412	    private Person person(String sheetId, long personId) {
413	        return people.findByIdAndSheetId(personId, sheetId)
414	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
415	    }
