418	    private static String record(String event, String sheetId, String user, Person person, Claim claim) {
419	        String number = claim.getNumber();
420	        return event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName()
421	                + " amount=" + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
422	                + (number != null ? " number=" + number : "");
